{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "National Emission Standards for Plastic Parts and Products Surface Coating",
      "gates": [
        {
          "type": "source_category",
          "question": "Do you perform surface coating of plastic parts or products (application of coating to a substrate and associated activities)?",
          "test": "Yes -> This source category (Subpart PPPP) may apply; No -> Subpart PPPP likely does not apply.",
          "citations": [
            "40 CFR 63.4481(a)(1)"
          ],
          "quote": "When application of coating to a substrate occurs, then surface coating also includes associated activities, such as surface preparation, cleaning, mixing, and storage."
        },
        {
          "type": "affected_source",
          "question": "Does the solvent step you describe fall within the affected source definition (i.e., is it part of the collection of coating operations, storage, mixing, conveyance, or waste handling used for surface coating of plastic parts)?",
          "test": "Yes -> That operation is within the affected source and is considered by this subpart; No -> That operation may not be covered by the affected-source scope of this subpart.",
          "citations": [
            "40 CFR 63.4482(b)"
          ],
          "quote": "The affected source is the collection of all of the items listed in paragraphs (b)(1) through (4) of this section that are used for surface coating of plastic parts and products within each subcategory."
        },
        {
          "type": "affected_source",
          "question": "Is the material you apply (including adhesives/solvent welding fluids) considered a 'coating' (coating includes adhesives) when applied to the plastic substrate?",
          "test": "Yes -> The applied material is treated as a coating under this subpart; No -> The material may not meet the subpart's coating definition and may not be covered as a coating operation.",
          "citations": [
            "40 CFR 63.4581"
          ],
          "quote": "Coating means a material applied to a substrate for decorative, protective, or functional purposes. Such materials include, but are not limited to, paints, sealants, liquid plastic coatings, caulks, inks, adhesives, and maskants."
        },
        {
          "type": "major_or_area",
          "question": "Is the coating activity located at or part of a major source of HAP (i.e., source emits or has potential to emit ≥10 tons/year of a single HAP)?",
          "test": "Yes -> The facility meets the major-source criterion referenced by this subpart; No -> The facility may not meet the major-source criterion and this subpart's applicability condition may not be met.",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "emits or has the potential to emit any single HAP at a rate of 9.07 megagrams (Mg) (10 tons) or more per year."
        },
        {
          "type": "threshold",
          "question": "Does the affected source use 378 liters (100 gallons) or more per year of coatings that contain hazardous air pollutants in the surface coating of plastic parts and products?",
          "test": "Yes -> The use-threshold criterion for applicability to this subpart is met; No -> The affected source may be below the material-use threshold and Subpart PPPP may not apply on that basis.",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "that uses 378 liters (100 gallons (gal)) per year, or more, of coatings that contain hazardous air pollutants (HAP) in the surface coating of plastic parts and products;"
        },
        {
          "type": "exemption",
          "question": "Are the adhesives/coatings you apply 'products used on humans and animals' (for example, medical adhesives applied directly to people) such that they are excluded from being treated as adhesives under this subpart?",
          "test": "Yes -> Such products are excluded from the adhesive definition under this subpart and may not be covered as adhesives here; No -> The adhesive exclusion does not apply.",
          "citations": [
            "40 CFR 63.4581"
          ],
          "quote": "Products used on humans and animals, adhesive tape, contact paper, or any other product with an adhesive incorporated onto or in an inert substrate shall not be considered adhesives under this subpart."
        },
        {
          "type": "exemption",
          "question": "Does the facility use only coatings, thinners, additives, and cleaning materials that contain no organic HAP (such that the exclusion at §63.4481(c)(1) would apply)?",
          "test": "Yes -> The coating operation is excluded under paragraph (c)(1) and Subpart PPPP would not apply; No -> The exclusion does not apply based on presence of organic HAP.",
          "citations": [
            "40 CFR 63.4481(c)(1)"
          ],
          "quote": "A coating operation conducted at a facility where the facility uses only coatings, thinners and other additives, and cleaning materials that contain no organic HAP, as determined according to § 63.3941(a)."
        },
        {
          "type": "compliance_date",
          "question": "Is the affected source new (did you commence construction after December 4, 2002 by installing new coating equipment used to coat plastic parts where no such coating was previously performed)?",
          "test": "Yes -> New-source provisions and the new-source emission limits may apply; No -> Existing-source emission limits and provisions apply.",
          "citations": [
            "40 CFR 63.4482(c)(1)",
            "40 CFR 63.4482(c)(2)"
          ],
          "quote": "You commenced the construction of the source after December 4, 2002 by installing new coating equipment. The new coating equipment is used to coat plastic parts and products at a source where no plastic parts surface coating was previously performed."
        }
      ],
      "missing": [
        "Annual volume (gallons or liters per year) of the methylene chloride or other HAP-containing materials used in the solvent-welding/bonding lines (per line and facility total).",
        "Whether the solvent application is performed for the purpose of bonding (i.e., is it applied as an adhesive/adhesive coating) versus a non-coating activity (e.g., cleaning), and whether any dry film or solids remain after application.",
        "Whether the adhesives/coatings applied are themselves 'products used on humans and animals' (i.e., medical adhesives applied directly to people) such that the adhesive exclusion might apply.",
        "Confirmation of the facility's major-source status in HAP tons/year (single HAP ≥10 tpy or combined HAP ≥25 tpy) as referenced in § 63.4481(b).",
        "Whether the new lines meet the regulatory definition of a new or reconstructed affected source (construction commencement date and whether coating was previously performed at those locations)."
      ]
    }
  ],
  "checklist": [
    {
      "item": "Confirm whether the solvent application is performed for the purpose of bonding plastic parts (i.e., applied as an adhesive/adhesive coating).",
      "gate": "affected_source"
    },
    {
      "item": "Report the annual volume (gallons or liters per year) of HAP-containing materials (methylene chloride) used on the solvent-welding lines and facility-wide.",
      "gate": "threshold"
    },
    {
      "item": "Confirm the facility's major-source status (tons per year of single and combined HAP emissions).",
      "gate": "major_or_area"
    },
    {
      "item": "Confirm whether the adhesives/coatings applied are 'products used on humans and animals' (medical adhesives applied directly to people).",
      "gate": "exemption"
    },
    {
      "item": "Confirm construction/installation dates for the new lines to determine new versus existing source status relative to December 4, 2002.",
      "gate": "compliance_date"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "FFFFFF",
      "title": "Secondary Copper Smelters",
      "gates": [
        {
          "type": "source_category",
