        },
        {
          "type": "affected_source",
          "question": "Did you commence construction or reconstruction of the affected source on or after October 6, 2006 (i.e., is this a new affected source)?",
          "test": "Yes: the source would be a new affected source under this subpart; No: the source would not be a 'new' affected source under this subpart.",
          "citations": [
            "40 CFR 63.11153(b)"
          ],
          "quote": "Your secondary copper smelter is a new affected source if you commenced constructed or reconstruction of the affected source on or after October 6, 2006."
        },
        {
          "type": "affected_source",
          "question": "Does the facility operate a smelting furnace, melting furnace, or other vessel that contains molten material (e.g., a furnace handling molten copper) such that capture of gases/fumes would be required?",
          "test": "Yes: the requirement for a capture system for each smelting/melting furnace may apply; No: the capture-system requirement for such vessels would not apply.",
          "citations": [
            "40 CFR 63.11155(b)"
          ],
          "quote": "For each smelting furnace, melting furnace, or other vessel that contains molten material, you must install and operate a capture system that collects the gases and fumes from the vessel"
        },
        {
          "type": "major_or_area",
          "question": "Is the facility an area source of hazardous air pollutant (HAP) emissions?",
          "test": "Yes: the subpart may apply only to area sources as described; No: the subpart's area-source applicability would not be met.",
          "citations": [
            "40 CFR 63.11153(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate a new secondary copper smelter that is an area source of hazardous air pollutant (HAP) emissions."
        },
        {
          "type": "compliance_date",
          "question": "Did you start up the new affected source after January 23, 2007?",
          "test": "Yes: you must achieve compliance upon startup; No: you must have achieved compliance by January 23, 2007.",
          "citations": [
            "40 CFR 63.11154(b)"
          ],
          "quote": "If you startup a new affected source after January 23, 2007, you must achieve compliance with the applicable provisions of this subpart upon startup of your affected source."
        }
      ],
      "missing": [
        "Whether the facility actually produces anode copper from copper scrap using a pyrometallurgical purification process (versus merely melting scrap for ingots or direct use).",
        "The facility construction/reconstruction date to determine 'new' status (on or after October 6, 2006).",
        "Quantification or determination of whether the facility is an area source or a major source of HAPs (emission totals vs. major-source thresholds).",
        "Whether the specific furnaces/vessels at the facility are 'smelting furnaces' or 'melting furnaces' as used in the subpart and whether they will have capture systems."
      ]
    },
    {
      "subpart": "ZZZZZZ",
      "title": "Area Source Standards for Aluminum, Copper, and Other Nonferrous Foundries",
      "gates": [
        {
          "type": "source_category",
          "question": "Does the facility melt copper or copper-based alloys and pour molten copper into molds to manufacture complex copper castings (i.e., operate as a copper foundry)?",
          "test": "Yes: facility fits the copper foundry source category; No: facility is not a copper foundry under this subpart.",
          "citations": [
            "40 CFR 63.11556"
          ],
          "quote": "Copper foundry means a foundry that melts copper or copper-based alloys and pours molten copper or copper-based alloys into molds to manufacture copper or copper-based alloy castings (excluding die casting) that are complex shapes."
        },
        {
          "type": "exemption",
          "question": "Does the facility instead act as a primary or secondary metal producer that casts molten copper to produce simple shapes such as sows, ingots, billets, bars, anode copper, rods, or copper cake?",
          "test": "Yes: the facility is excluded from the 'copper foundry' definition for this subpart; No: the exclusion does not apply.",
          "citations": [
            "40 CFR 63.11556"
          ],
          "quote": "For purposes of this subpart, this definition does not include primary or secondary metal producers that cast molten copper to produce simple shapes such as sows, ingots, billets, bars, anode copper, rods, or copper cake."
        },
        {
          "type": "major_or_area",
          "question": "Is the facility an area source of hazardous air pollutant (HAP) emissions and otherwise meeting the applicability criteria in §63.11544(a)?",
          "test": "Yes: the foundry subpart may apply (subject to other specific criteria); No: this subpart's area-source applicability is not met.",
          "citations": [
            "40 CFR 63.11544(a)"
          ],
          "quote": "that is an area source of hazardous air pollutant (HAP) emissions as defined in § 63.2 and meets the criteria specified in paragraphs (a)(1) through (4) of this section."
        },
        {
          "type": "threshold",
          "question": "For new affected sources, does the facility have an annual copper and other nonferrous foundry metal melt capacity of at least 600 tons per year?",
          "test": "Yes: the 600 tpy threshold criterion in paragraph (a)(4) is met; No: the 600 tpy threshold criterion is not met.",
          "citations": [
            "40 CFR 63.11544(a)(4)"
          ],
          "quote": "has an annual metal melt production (for existing affected sources) or an annual metal melt capacity (for new affected sources) of at least 600 tons per year (tpy) of aluminum, copper, and other nonferrous metals"
