      ],
      "missing": [
        "Whether the facility pours molten copper into molds to manufacture complex castings versus producing simple shapes (anode copper, ingots, sows, etc.).",
        "The facility's annual metal melt production or capacity (to compare to the 600 tpy threshold).",
        "Whether the facility is an area source of HAP emissions (emission totals vs. major-source thresholds)."
      ]
    },
    {
      "subpart": "TTTTTT",
      "title": "Secondary Nonferrous Metals Processing Area Source Rule",
      "gates": [
        {
          "type": "source_category",
          "question": "Does the facility meet the definition of a secondary nonferrous metals processing facility in §63.11472 (i.e., operate as a secondary nonferrous metals processor)?",
          "test": "Yes: facility may be in the secondary nonferrous metals processing source category; No: facility is not in that source category.",
          "citations": [
            "40 CFR 63.11462(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate a secondary nonferrous metals processing facility (as defined in § 63.11472) that is an area source of hazardous air pollutant (HAP) emissions."
        },
        {
          "type": "major_or_area",
          "question": "Is the facility an area source of hazardous air pollutant (HAP) emissions?",
          "test": "Yes: the subpart's area-source applicability condition may be met; No: the subpart's area-source applicability condition is not met.",
          "citations": [
            "40 CFR 63.11462(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate a secondary nonferrous metals processing facility (as defined in § 63.11472) that is an area source of hazardous air pollutant (HAP) emissions."
        }
      ],
      "missing": [
        "The text of §63.11472 (definition of 'secondary nonferrous metals processing facility') to determine whether the facility fits that definition.",
        "Whether the facility is an area source of HAP emissions (emission totals vs. major-source thresholds)."
      ]
    }
  ],
  "checklist": [
    {
      "item": "Does the facility process copper scrap using a pyrometallurgical purification process to produce anode copper (i.e., produce anode copper from scrap)?",
      "gate": "source_category"
    },
    {
      "item": "Did construction or reconstruction of the affected source commence on or after October 6, 2006?",
      "gate": "affected_source"
    },
    {
      "item": "Does the facility operate smelting or melting furnaces or other vessels that contain molten material (requiring capture systems)?",
      "gate": "affected_source"
    },
    {
      "item": "Is the facility an area source of HAP emissions (vs. a major source)?",
      "gate": "major_or_area"
    },
    {
      "item": "For foundry rule consideration: does the facility pour molten copper into molds to make complex castings, or does it cast simple shapes (anode copper, ingots, sows, billets, bars, rods, or copper cake)?",
      "gate": "exemption"
    },
    {
      "item": "What is the facility's annual metal melt production or capacity (tpy) to compare to the 600 tpy foundry threshold?",
      "gate": "threshold"
    },
    {
      "item": "If relying on Subpart FFFFFF: did you start up the new affected source after January 23, 2007?",
      "gate": "compliance_date"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "M",
      "title": "Perchloroethylene dry cleaning (Subpart M)",
      "gates": [
        {
          "type": "affected_source",
          "question": "Is your dry cleaning system located in a building with a residence (including a residence that is currently vacant)?",
          "test": "yes -> subject to the building-with-residence requirements in this subpart; no -> building-with-residence requirements do not apply",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ],
          "quote": "After December 21, 2020, the owner or operator shall eliminate any emission of PCE from any dry cleaning system that is located in a building with a residence."
        },
        {
          "type": "major_or_area",
          "question": "Does the facility emit or have the potential to emit more than 9.1 megagrams per year (10 tons per year) of perchloroethylene?",
          "test": "yes -> facility is a major source; no -> facility is an area source",
          "citations": [
            "40 CFR 63.320(g)"
          ],
          "quote": "A dry cleaning facility is a major source if the facility emits or has the potential to emit more than 9.1 megagrams per year (10 tons per year) of perchloroethylene to the atmosphere."
        },
        {
          "type": "threshold",
          "question": "Is the total yearly PCE consumption at the dry cleaning facility less than 530 liters (140 gallons) per year?",
          "test": "yes -> certain existing systems may be exempt from many provisions under §63.320(d); no -> those exemptions do not apply",
          "citations": [
            "40 CFR 63.320(d)"
          ],
          "quote": "if the total PCE consumption of the dry cleaning facility is less than 530 liters (140 gallons) per year. Consumption is determined according to § 63.323(d)."
        },
        {
          "type": "compliance_date",
          "question": "Does the owner/operator need to eliminate emissions from systems located in buildings with residences by the specified date?",
          "test": "yes -> elimination requirement applies after the date cited; no -> elimination requirement not triggered by that date for systems not in buildings with residences",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ],
          "quote": "After December 21, 2020, the owner or operator shall eliminate any emission of PCE from any dry cleaning system that is located in a building with a residence."
        },
        {
          "type": "affected_source",
          "question": "When you notify authorities, should you report that the facility is located in a building with a residence even if the residence is vacant?",
          "test": "yes -> you must report that you are located in a building with a residence even if vacant; no -> reporting would indicate not located in a building with a residence",
          "citations": [
            "40 CFR 63.324(f)(3)"
          ],
          "quote": "If they are located in a building with a residence(s), even if the residence is vacant at the time of this notification;"
        }
      ],
      "missing": []
    },
    {
      "subpart": "A",
      "title": "General Provisions (Subpart A)",
      "gates": [
        {
          "type": "compliance_date",
          "question": "If this is an existing affected source, is there a compliance date established in the applicable subpart that determines when you must comply?",
          "test": "yes -> comply by the compliance date established in the applicable subpart; no -> other general compliance timing rules may apply",
          "citations": [
            "40 CFR 63.6(c)(1)"
          ],
          "quote": "After the effective date of a relevant standard established under this part pursuant to section 112(d) or 112(h) of the Act, the owner or operator of an existing source shall comply with such standard by the compliance date established by the Administrator in the applicable subpart(s) of this part,"
        }
      ],
      "missing": []
    },
    {
      "subpart": "EEEE",
      "title": "General requirements for Subpart EEEE (Subpart EEEE)",
      "gates": [
        {
          "type": "affected_source",
          "question": "Must you operate and maintain your affected source and control/monitoring equipment according to §63.6(e)(1)(i)?",
          "test": "yes -> you must operate and maintain according to §63.6(e)(1)(i); no -> §63.2350(b) would not impose that obligation for your equipment",
          "citations": [
            "40 CFR 63.2350(b)"
          ],
          "quote": "Except as specified in paragraph (d) of this section, you must always operate and maintain your affected source, including air pollution control and monitoring equipment, according to the provisions in § 63.6(e)(1)(i)."
        }
      ],
      "missing": []
    }
  ],
  "checklist": [
    {
      "item": "Is the dry cleaning machine located in a building that contains a residence (even if that residence is currently vacant)?",
      "gate": "affected_source"
    },
    {
      "item": "What is the facility's yearly PCE consumption (12-month sum of PCE purchases)?",
      "gate": "threshold"
    },
    {
      "item": "Does the facility emit or have the potential to emit more than 9.1 megagrams (10 tons) per year of PCE?",
      "gate": "major_or_area"
    },
    {
      "item": "Is the dry cleaning system an existing source with a compliance date specified in the applicable subpart, or is it a new source?",
      "gate": "compliance_date"
    },
    {
      "item": "When you notify the authority, will you report that the facility is located in a building with a residence (even if vacant)?",
      "gate": "affected_source"
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "LLL",
      "title": "National Emission Standards for Hazardous Air Pollutants from the Portland Cement Manufacturing Industry",
      "gates": [
        {
          "type": "source_category",
          "question": "Is your facility a portland cement plant?",
          "test": "yes -> Consider Subpart LLL; no -> Subpart LLL does not apply",
          "citations": [
            "40 CFR 63.1340(a)"
          ],
          "quote": "The provisions of this subpart apply to each new and existing portland cement plant which is a major source or an area source as defined in § 63.2."
        },
        {
          "type": "affected_source",
          "question": "Does the coal mill use kiln exhaust gases in its process (i.e., is it an in-line coal mill)?",
          "test": "yes -> The coal mill is an in-line coal mill and is treated as part of the kiln for this subpart; no -> It is not an in-line coal mill and may not be an affected source under this subpart",
          "citations": [
            "40 CFR 63.1341"
          ],
          "quote": "In-line coal mill means a coal mill using kiln exhaust gases in their process. A coal mill with a heat source other than the kiln or a coal mill using exhaust gases from the clinker cooler is not an in-line coal mill."
        },
        {
          "type": "major_or_area",
          "question": "Is the portland cement plant a major source or an area source as defined in § 63.2?",
          "test": "yes -> The plant falls within Subpart LLL's scope (major or area source); no -> Subpart LLL does not apply as written here",
          "citations": [
            "40 CFR 63.1340(a)"
          ],
          "quote": "The provisions of this subpart apply to each new and existing portland cement plant which is a major source or an area source as defined in § 63.2."
        },
        {
          "type": "threshold",
          "question": "Does the coal mill exhaust through its own separate stack associated with the kiln?",
          "test": "yes -> Combined PM emissions from kiln and inline coal mill stack are subject to the PM limit and must be accounted for; no -> If exhaust is combined into the kiln stream, an alternative PM limit calculation may apply",
          "citations": [
            "40 CFR 63.1343(b)(2)"
          ],
          "quote": "When there is an alkali bypass and/or an inline coal mill with a separate stack associated with a kiln, the combined PM emissions from the kiln and the alkali bypass stack and/or the inline coal mill stack are subject to the PM emissions limit."
        },
        {
          "type": "threshold",
          "question": "Is the coal mill exhaust combined with the kiln exhaust and sent to the PM control device as a single stream?",
          "test": "yes -> You may meet an alternative PM emissions limit calculated per the rule for commingled sources; no -> Combined emissions from separate stacks must be computed as separate streams and combined for limits",
          "citations": [
            "40 CFR 63.1343(b)(2)"
          ],
          "quote": "Existing kilns that combine the clinker cooler exhaust and/or alkali bypass and/or coal mill exhaust with the kiln exhaust and send the combined exhaust to the PM control device as a single stream may meet an alternative PM emissions limit."
        },
        {
          "type": "threshold",
          "question": "Is the kiln (and therefore associated inline equipment) a new source (construction or reconstruction after May 6, 2009) for purposes of the Subpart LLL limits?",
          "test": "yes -> New-source emission limits (e.g., lower PM lb/ton) apply; no -> Existing-source limits apply",
          "citations": [
            "40 CFR 63.1341"
          ],
          "quote": "New source means any source that commenced construction or reconstruction after May 6, 2009, for purposes of determining the applicability of the kiln, clinker cooler and raw material dryer emissions limits for mercury, PM, THC, and HCl."
        },
        {
          "type": "exemption",
          "question": "Is the coal mill instead subject to standards for nonmetallic mineral processing plants in part 60 subpart OOO (i.e., excluded from Subpart LLL)?",
          "test": "yes -> That onsite source is not subject to Subpart LLL; no -> Subpart LLL remains potentially applicable",
          "citations": [
            "40 CFR 63.1340(c)"
          ],
          "quote": "Onsite sources that are subject to standards for nonmetallic mineral processing plants in subpart OOO, part 60 of this chapter are not subject to this subpart. Crushers are not covered by this subpart regardless of their location."
        },
        {
          "type": "compliance_date",
          "question": "Is PM compliance to be demonstrated by a Method 5 or 5I performance test with ongoing PM CPMS monitoring?",
          "test": "yes -> Conduct Method 5/5I performance testing and install/operate PM CPMS per the rule; no -> If not subject to PM limit, these demonstrations may not be required under this subpart",
          "citations": [
            "40 CFR 63.1349(b)(1)"
          ],
          "quote": "The owner or operator of a kiln and clinker cooler subject to limitations on PM emissions shall demonstrate initial compliance by conducting a performance test using Method 5 or Method 5I at appendix A-3 to part 60 of this chapter. You must also monitor continuous performance through use of a PM continuous parametric monitoring system (PM CPMS)."
        },
        {
          "type": "compliance_date",
          "question": "If the coal mill has a separate stack, must the kiln main exhaust and the coal mill stack be tested simultaneously and the combined PM emission rate computed?",
          "test": "yes -> Test main exhaust and coal mill simultaneously and compute combined emission rate per the rule; no -> If not separate, alternate commingled procedures apply",
          "citations": [
            "40 CFR 63.1349(b)(1)(viii)"
          ],
          "quote": "When there is an alkali bypass and/or an inline coal mill with a separate stack associated with a kiln, the main exhaust and alkali bypass and/or inline coal mill must be tested simultaneously and the combined emission rate of PM from the kiln and alkali bypass and/or inline coal mill must be computed for each run using Equation 8 of this section."
        },
        {
          "type": "compliance_date",
          "question": "Must THC, mercury, and HCl emissions from diverted kiln gases (including coal mill stacks) be measured and accounted for as specified (e.g., measure upstream or in coal mill stack; use CEMS or prescribed performance tests)?",
          "test": "yes -> Follow the specified measurement locations and methods (CEMS, sorbent traps, Method 320/321, etc.); no -> If not subject to those pollutant limits, these specific demonstrations may not apply",
          "citations": [
            "40 CFR 63.1349(b)(4)",
            "40 CFR 63.1350(k)(5)"
          ],
          "quote": "THC must be measured either upstream of the coal mill or the coal mill stack. If kiln gases are diverted through an alkali bypass or to a coal mill and exhausted through separate stacks, you must account for the mercury emitted from those stacks by following the procedures in (k)(5)(i) through (iv) of this section."
        },
        {
